from abc import ABCMeta, abstractmethod


class Factory(object):

    _mandatory_parameters = set()
    _optional_parameters = set()

    @classmethod
    def _get_all_parameters(cls, parameter_name):
        parameters = set()
        for member_cls in cls.__mro__:
            if member_cls is not object:
                parameters |= getattr(member_cls, parameter_name, set())
        return parameters

    @property
    def product_class(self):
        return self._product_class

    def create(self, configuration, existing_arguments=None):
        """
        Create an object from configuration parameters and/or existing arguments.

        :param dict configuration:
            collection of configuration parameters for the object to be created and other objects,
            that might have to be created as prerequisites
        :param dict existing_arguments:
            existing arguments for the final constructor call, that don't need to be created
            (dict with constructor parameter name as key and argument value as value)

        :return: created object
        """
        resulting_arguments = {}
        self._build_arguments(configuration=configuration,
                              existing_arguments=existing_arguments if existing_arguments else {},
                              resulting_arguments=resulting_arguments)
        return self._product_class(**resulting_arguments)

    def _build_arguments(self, configuration, existing_arguments, resulting_arguments):
        """
        Build the arguments for the final constructor call.

        A class with multiple levels of base classes has multiple levels of factory base classes,
        where each factory base class adds certain keyword arguments to the arguments
        for the final constructor call.

        :param dict configuration:
            collection of configuration parameters for the object to be created and other objects,
            that might have to be created as prerequisites
        :param dict existing_arguments:
            existing arguments for the final constructor call, that don't need to be created
            (dict with constructor parameter name as key and argument value as value)
        :param dict resulting_arguments:
            resulting arguments for the final constructor call
            (dict with constructor parameter name as key and argument value as value)
        """
        for parameter_name in self._get_all_parameters("_mandatory_parameters"):
            resulting_arguments[parameter_name] = configuration[parameter_name]
        for parameter_name in self._get_all_parameters("_optional_parameters"):
            if parameter_name in configuration:
                resulting_arguments[parameter_name] = configuration[parameter_name]
        for parameter_name in existing_arguments:
            resulting_arguments[parameter_name] = existing_arguments[parameter_name]


class ReusableFactory(Factory, metaclass=ABCMeta):

    @staticmethod
    @abstractmethod
    def _create_unique_key(resulting_arguments):
        """Return tuple of (unique_key, reuse_flag)."""
        pass

    def create(self, configuration, existing_arguments=None):
        """
        Create an object from configuration parameters and/or existing arguments.

        :param Union[dict,list] configuration:
            collection of configuration parameters for the object to be created and other objects,
            that might have to be created as prerequisites
        :param dict existing_arguments:
            existing arguments for the final constructor call, that don't need to be created
            (dict with constructor parameter name as key and argument value as value)

        :return: created object
        """
        resulting_arguments = {}
        self._build_arguments(configuration=configuration,
                              existing_arguments=existing_arguments if existing_arguments else {},
                              resulting_arguments=resulting_arguments)
        return self._reuse_product_object_if_available(resulting_arguments)

    def _reuse_product_object_if_available(self, resulting_arguments):
        unique_key, reuse = self._create_unique_key(resulting_arguments)
        if reuse and unique_key in self._existing_product_objects:
            return self._existing_product_objects[unique_key]
        new_object = self._product_class(**resulting_arguments)
        self._existing_product_objects.setdefault(unique_key, new_object)
        return new_object
